<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kanban Board</title>
<style>
  * { box-sizing: border-box; }
  body {
    font-family: system-ui, -apple-system, sans-serif;
    background: #f4f5f7;
    margin: 0;
    padding: 20px;
    color: #172b4d;
  }
  h1 { margin-top: 0; font-size: 24px; }
  .controls {
    margin-bottom: 20px;
    display: flex;
    gap: 10px;
  }
  #new-card {
    padding: 10px 12px;
    font-size: 14px;
    border: 1px solid #dfe1e6;
    border-radius: 4px;
    width: 300px;
    outline: none;
  }
  #new-card:focus { border-color: #0052cc; }
  #add-card {
    padding: 10px 16px;
    font-size: 14px;
    background: #0052cc;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 500;
  }
  #add-card:hover { background: #0043a6; }

  .board {
    display: flex;
    gap: 20px;
    align-items: flex-start;
  }
  .column {
    background: #ebecf0;
    border-radius: 8px;
    width: 300px;
    padding: 12px;
    display: flex;
    flex-direction: column;
    min-height: 400px;
    transition: background 0.2s;
  }
  .column.drag-over {
    background: #dfe1e6;
  }
  .column h2 {
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin: 0 0 12px 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    color: #42526e;
  }
  .count {
    background: #fff;
    color: #42526e;
    font-size: 12px;
    padding: 2px 8px;
    border-radius: 12px;
    font-weight: 600;
  }
  .card-container {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 10px;
  }
  .card {
    background: #fff;
    border-radius: 4px;
    padding: 12px;
    box-shadow: 0 1px 2px rgba(9,30,66,0.25);
    cursor: grab;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 8px;
  }
  .card:active { cursor: grabbing; }
  .card-title {
    word-break: break-word;
    font-size: 14px;
    line-height: 1.4;
  }
  .card-del {
    background: transparent;
    border: none;
    color: #6b778c;
    cursor: pointer;
    font-size: 18px;
    line-height: 1;
    padding: 0 4px;
    border-radius: 4px;
  }
  .card-del:hover { 
    color: #de350b; 
    background: #ffebe6;
  }
</style>
</head>
<body>

  <h1>Kanban Board</h1>
  <div class="controls">
    <input type="text" id="new-card" placeholder="Enter a task..." />
    <button id="add-card">Add Card</button>
  </div>

  <div class="board">
    <div class="column" id="col-todo">
      <h2>To Do <span class="count">0</span></h2>
      <div class="card-container"></div>
    </div>
    <div class="column" id="col-doing">
      <h2>Doing <span class="count">0</span></h2>
      <div class="card-container"></div>
    </div>
    <div class="column" id="col-done">
      <h2>Done <span class="count">0</span></h2>
      <div class="card-container"></div>
    </div>
  </div>

<script>
  let state = [];
  const STORAGE_KEY = 'kanbanState';

  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed)) {
        state = parsed;
      }
    }
  } catch (e) {
    console.error('Failed to load state', e);
  }

  let draggedCardId = null;

  function saveState() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (e) {
      console.error('Failed to save state', e);
    }
  }

  function createCardElement(card) {
    const div = document.createElement('div');
    div.className = 'card';
    div.draggable = true;
    div.dataset.id = card.id;

    const span = document.createElement('span');
    span.className = 'card-title';
    span.textContent = card.title;

    const btn = document.createElement('button');
    btn.className = 'card-del';
    btn.innerHTML = '&times;';
    btn.title = 'Delete card';
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      state = state.filter(c => c.id !== card.id);
      saveState();
      render();
    });

    div.appendChild(span);
    div.appendChild(btn);

    div.addEventListener('dragstart', (e) => {
      draggedCardId = card.id;
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', card.id);
    });

    div.addEventListener('dragend', () => {
      draggedCardId = null;
      document.querySelectorAll('.column').forEach(c => c.classList.remove('drag-over'));
    });

    return div;
  }

  function render() {
    const containers = {
      todo: document.querySelector('#col-todo .card-container'),
      doing: document.querySelector('#col-doing .card-container'),
      done: document.querySelector('#col-done .card-container')
    };

    Object.values(containers).forEach(c => c.innerHTML = '');

    const counts = { todo: 0, doing: 0, done: 0 };

    state.forEach(card => {
      if (!containers[card.column]) {
        card.column = 'todo';
      }
      const el = createCardElement(card);
      containers[card.column].appendChild(el);
      counts[card.column]++;
    });

    document.querySelector('#col-todo .count').textContent = counts.todo;
    document.querySelector('#col-doing .count').textContent = counts.doing;
    document.querySelector('#col-done .count').textContent = counts.done;
  }

  const addBtn = document.getElementById('add-card');
  const input = document.getElementById('new-card');

  addBtn.addEventListener('click', () => {
    const title = input.value.trim();
    if (title) {
      state.push({
        id: 'card-' + Date.now() + '-' + Math.floor(Math.random() * 1000),
        title: title,
        column: 'todo'
      });
      input.value = '';
      saveState();
      render();
    }
  });

  input.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      addBtn.click();
    }
  });

  function handleDragOver(e) {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    e.currentTarget.classList.add('drag-over');
  }

  function handleDragLeave(e) {
    if (!e.currentTarget.contains(e.relatedTarget)) {
      e.currentTarget.classList.remove('drag-over');
    }
  }

  function handleDrop(e) {
    e.preventDefault();
    e.currentTarget.classList.remove('drag-over');

    let id = e.dataTransfer.getData('text/plain');
    if (!id && draggedCardId) {
      id = draggedCardId;
    }

    if (id) {
      const targetColId = e.currentTarget.id;
      const targetCol = targetColId.replace('col-', '');

      const card = state.find(c => c.id === id);
      if (card && card.column !== targetCol) {
        card.column = targetCol;
        saveState();
        render();
      }
    }
    draggedCardId = null;
  }

  ['col-todo', 'col-doing', 'col-done'].forEach(id => {
    const col = document.getElementById(id);
    col.addEventListener('dragover', handleDragOver);
    col.addEventListener('dragleave', handleDragLeave);
    col.addEventListener('drop', handleDrop);
  });

  render();
</script>
</body>
</html>
